WITH daily AS (SELECT order_date,SUM(oi.quantity*oi.unit_price*(1-oi.discount)) revenue FROM orders o JOIN order_items oi USING(order_id) WHERE order_status='completed' GROUP BY order_date), stats AS (SELECT AVG(revenue) mean_revenue,AVG(revenue*revenue) mean_square FROM daily) SELECT daily.*,CASE WHEN revenue > mean_revenue+2*sqrt(mean_square-mean_revenue*mean_revenue) THEN 'high spike' WHEN revenue < mean_revenue-2*sqrt(mean_square-mean_revenue*mean_revenue) THEN 'low drop' END anomaly FROM daily,stats;
